/// Count how many mirror‐pairs (j, a.len()-1-j) with j < k are mismatched.
#[verifier::spec]
fn mismatches_prefix(a: Seq<i8>, k: nat) -> nat {
    if k == 0 {
        0
    } else {
        let j = k - 1;
        let prev = mismatches_prefix(a, j);
        if j < a.len() / 2 && a.index(j) != a.index(a.len() - 1 - j) {
            prev + 1
        } else {
            prev
        }
    }
}

/// Total number of mismatched pairs in `a`.
#[verifier::spec]
fn mismatches_spec(a: Seq<i8>) -> nat {
    mismatches_prefix(a, a.len() / 2)
}

