#[requires(true)]
#[ensures(result == mismatches_spec(arr.view()))]
#[decreases(arr.len())]
fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    // View the Vec as a Seq so we can talk about it in our specs
    let seq: Seq<i8> = arr.view();

    let mut mismatches: usize = 0;
    let mut i: usize = 0;
    // We only need to iterate up to n/2
    while i < n / 2 {
        // Two loop invariants suffices to prove the post‐condition:
        //  1) 0 <= i <= n/2
        //  2) mismatches == mismatches_prefix(seq, i)
        #[invariant(i <= n / 2)]
        #[invariant(mismatches == mismatches_prefix(seq, i))]
        {
            if arr[i] != arr[n - 1 - i] {
                mismatches += 1;
            }
            i += 1;
        }
    }

    // At this point i == n/2, so mismatches == mismatches_prefix(seq, n/2)
    // which by definition is mismatches_spec(seq) and closes the post‐condition.
    mismatches
}

